    await _refreshConfig();
    if (_maintaining) return false;
    _maintaining = true;
    try {
      for (final store in [await projectStore, await userStore]) {
        if (store == null) continue;
        await store.maintainMemoryLevels();
        if (_llmProvider != null) {
          try {
            await store.consolidate();
